mapper.select:
/* BmsCargoAbnormalMapper.selectAbnormalList : 배송지변경신고 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,odAdnor.AR_DATE ,odAdnor.MRN ,odAdnor.MSN ,od.MBL_NO ,od.BOUND ,od.BOUND_TYPE ,COUNT(1) OVER (PARTITION BY od.OD_JOB_NO) AS HBL_CNT ,od.SHIPPER_ATTN ,od.HBL_NO ,od.MASTER_OD_JOB_NO ,od.HSN
,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE od.PIECES END AS HBL_PIECES ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE od.GWT END AS HBL_GWT ,odAdnor.PIECES ,odAdnor.GWT ,odAdnor.CNT ,odAdnor.ABNORMAL_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = odAdnor.ABNORMAL_CODE AND GROUP_CODE = 'ABNORMALITY_CODE') AS ABNORMAL_CODE_NAME ,odAdnor.DISC_WH_CODE ,CASE WHEN odAdnor.SEND_DATE IS NULL THEN 'N' ELSE 'Y' END AS SEND_YN ,odAdnor.SEQ_NO_ID ,odAdnor.REGISTER_DATE_TIME ,od.VENDER_ID_1 as VENDER_ID1 FROM TB_ECM_OD od INNER JOIN TB_ECM_OD mod ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO INNER JOIN TB_ECM_OD_ABNORMAL odAdnor ON od.OD_JOB_NO = odAdnor.OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode} AND ISNULL(odAdnor.SEND_DATE,'') = ''
AND odAdnor.ABNORMAL_CODE = #{srchAbnormalCode}
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND od.OD_JOB_NO IN (
#{item.odJobNo}
)

/* BmsCargoAbnormalMapper.selectBmsInPlanAbnormalList : 배송지변경신고 List(반입예정데이터) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT * FROM ( SELECT bip.OD_JOB_NO AS OD_JOB_NO , bip.AR_DATE , (CASE WHEN bip.CARGO_REFERENCE_NO IS NULL THEN '' ELSE SUBSTRING(bip.CARGO_REFERENCE_NO, 1, 11) END) AS MRN , (CASE WHEN bip.CARGO_REFERENCE_NO IS NULL THEN '' ELSE SUBSTRING(bip.CARGO_REFERENCE_NO, 12, 4) END) AS MSN , bip.MBL_NO , 'AIR' AS BOUND , 'IMP' AS BOUND_TYPE , COUNT(1) OVER (PARTITION BY bip.IN_PLAN_NO) AS HBL_CNT , abnormal.REGISTER_USER_ID AS SHIPPER_ATTN , bip.BL_NO AS HBL_NO , SUBSTRING(bip.CARGO_REFERENCE_NO, 16, 4) AS HSN , bip.EX_CT AS HBL_PIECES , bip.EX_WT AS HBL_GWT , bip.VESSEL_FLIGHT , ISNULL(ISNULL(abnormal.PIECES, bip.EX_CT), 0) AS PIECES , ISNULL(ISNULL(abnormal.GWT, bip.EX_WT), 0) AS GWT , ISNULL(abnormal.CNT, 0) AS CNT , ISNULL(abnormal.ABNORMAL_CODE, '') AS ABNORMAL_CODE , '' AS ABNORMAL_CODE_NAME
, 'N' AS SEND_YN , 0 AS SEQ_NO_ID , CASE WHEN abnormal.REGISTER_DATE_TIME = '1900-01-01 00:00:00.000' THEN '' ELSE abnormal.REGISTER_DATE_TIME END AS REGISTER_DATE_TIME , 'QQ' AS VENDER_ID1 , ROW_NUMBER() OVER (PARTITION BY CASE WHEN bip.CARGO_REFERENCE_NO IS NULL THEN '' ELSE SUBSTRING(bip.CARGO_REFERENCE_NO, 1, 11) END, bip.MBL_NO, bip.BL_NO ORDER BY bip.OD_JOB_NO) AS RN , bip.ORIG_COUNTRY , CAST(bi.CARRYIN_DATE + ' ' + bi.CARRYIN_TIME AS DATETIME) AS CARRYIN_DATE FROM TB_BMS_IN_PLAN bip WITH (NOLOCK) LEFT JOIN TB_BMS_IN bi WITH (NOLOCK) ON bi.IN_PLAN_NO = bip.IN_PLAN_NO LEFT JOIN TB_ECM_OD_PANTOS_ABNORMAL abnormal ON abnormal.OD_JOB_NO = bip.OD_JOB_NO
WHERE 1=1
AND bip.IN_YN = 'Y' AND abnormal.ABNORMAL_CODE = 'MGN' AND abnormal.MANIFEST_DEL_YN = 'N'
AND NOT EXISTS (SELECT 1 FROM TB_ECM_OD_PANTOS_ABNORMAL WHERE OD_JOB_NO = bip.OD_JOB_NO AND ABNORMAL_CODE = #{srchAbnormalCode})
AND bip.IN_YN IN ('N', 'C') AND NOT EXISTS (SELECT 1 FROM TB_ECM_OD_PANTOS_ABNORMAL WHERE OD_JOB_NO = bip.OD_JOB_NO AND ABNORMAL_CODE = #{srchAbnormalCode})
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND bip.IN_PLAN_NO IN (
#{item.odJobNo}
)
) t WHERE t.RN = 1

/* BmsCargoAbnormalMapper.selectBmsInPlanAbnormalDeclareList : 배송지변경신고 List(반입예정데이터) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; WITH Main_CTE AS( SELECT A.* FROM ( SELECT X.*
FROM( SELECT bip.OD_JOB_NO AS OD_JOB_NO , odAdnor.SEQ_NO_ID , odAdnor.AR_DATE , odAdnor.MRN , odAdnor.MSN ,bip.MBL_NO ,bip.BL_NO AS HBL_NO ,SUBSTRING(bip.CARGO_REFERENCE_NO, 16, 4) AS HSN ,bip.VESSEL_FLIGHT ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE bip.EX_CT END AS HBL_PIECES ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 0 ELSE bip.EX_WT END AS HBL_GWT ,SUM(CASE WHEN odAdnor.ABNORMAL_CODE = 'MFN' THEN 1 ELSE 0 END ) OVER (PARTITION BY bip.OD_JOB_NO) AS MFN_CNT
,odAdnor.PIECES ,odAdnor.GWT ,odAdnor.CNT ,odAdnor.ABNORMAL_CODE ,CONCAT(odAdnor.ABNORMAL_CODE, '.', (SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = 'PANTK' AND CODE = odAdnor.ABNORMAL_CODE AND GROUP_CODE = 'ABNORMALITY_CODE')) AS ABNORMAL_CODE_NAME ,odAdnor.DISC_WH_CODE ,odAdnor.SEND_DATE ,ISNULL(odAdd.CARRYIN_DATE, '') AS CARRYIN_DATE ,ISNULL(odAdd.UNMANAGEMENT_DATE, '') AS UNMANAGEMENT_DATE ,ISNULL(odAdd.MF_CORRECTION_DATE, '') AS MF_CORRECTION_DATE ,ISNULL(odAdd.MF_CORRECTION_CONTENTS, '') AS MF_CORRECTION_CONTENTS ,ISNULL(odAdd.ABNORMAL_MFN_DATE, '') AS ABNORMAL_MFN_DATE ,ISNULL(odAdd.ABNORMAL_MFN_YN, '') AS ABNORMAL_MFN_YN ,SUBSTRING(bip.CARGO_REFERENCE_NO, 1, 11) AS MOD_MRN ,bip.SHIPPER_NAME ,bip.SHIPPER_TEL ,bip.CONSIGNEE_NAME ,bip.EX_CT AS MOD_PIECES ,bip.EX_WT AS MOD_GWT ,bip.COMMODITY_ITEM_LOC ,'AIR' AS BOUND ,ISNULL(odAdnor.LAST_POD_STATUS, '') AS LAST_POD_STATUS ,(SELECT TOP 1 MOD_TYPE FROM TB_EDI_MOD_HBL WHERE OD_JOB_NO = bip.OD_JOB_NO ORDER BY REGISTER_DATE_TIME DESC) AS MOD_TYPE ,'QQ' AS VENDER_ID1 ,(SELECT SEND_DATE FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = bip.OD_JOB_NO AND SEQ_NO_ID = 2) AS MGN_MFN_SEND_DATE
,dbo.Cryptography(bip.OD_JOB_NO, bip.CONSIGNEE_TEL, 1) AS CONSIGNEE_TEL
,bip.CONSIGNEE_TEL
,bip.MANIFEST_DEL_YN AS MANIFEST_DEL_YN ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MGN' AND DATEDIFF(DAY, SEND_DATE, GETDATE()) > 13 THEN 'Y' ELSE 'N' END AS NOT_PROCESS_YN ,CASE WHEN odAdnor.ABNORMAL_CODE = 'MGN' AND DATEDIFF(DAY, SEND_DATE, GETDATE()) <= 15 AND (bip.MANIFEST_DEL_YN = 'N' OR bip.IN_YN = 'N') THEN DATEDIFF(DAY, SEND_DATE, GETDATE()) ELSE -1 END AS MGN_MARK_DATE FROM TB_BMS_IN_PLAN bip WITH (NOLOCK) LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL odAdd ON bip.OD_JOB_NO = odAdd.OD_JOB_NO INNER JOIN TB_ECM_OD_ABNORMAL odAdnor ON bip.OD_JOB_NO = odAdnor.OD_JOB_NO AND odAdnor.SEQ_NO_ID = 1 WHERE 1=1
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchDateGbn} >= #{srchStartDate}
AND ${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(CHAR(10), #{srchEndDate}, ${srchDateFormat}))
AND odAdnor.ABNORMAL_CODE = #{srchAbnormalCode}
AND odAdnor.LAST_POD_STATUS = #{srchLastPodStatus}
AND bip.IN_YN = 'Y'
AND bip.IN_YN = 'N'
) X ) A
) , Count_CTE AS ( SELECT COUNT(*) AS TOTAL FROM Main_CTE ) SELECT *
, ROW_NUMBER() OVER(
, ${defaultSort2}
) AS NUM FROM Count_CTE, Main_CTE
, ${defaultSort2}
OFFSET ${startNum} ROWS FETCH NEXT ${pageSize} ROWS ONLY

/* BmsCargoAbnormalMapper.selectAbnormalAddPopupList : 하기이상추가팝업 List(반입예정데이터) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT SUBSTRING(bip.CARGO_REFERENCE_NO, 1, 11) AS MRN ,SUBSTRING(bip.CARGO_REFERENCE_NO, 12, 4) AS MSN ,bip.MBL_NO ,bip.VESSEL_FLIGHT ,'AIR' AS BOUND ,bip.BL_NO AS HBL_NO ,SUBSTRING(bip.CARGO_REFERENCE_NO, 16, 4) AS HSN ,bip.EX_CT AS OD_PIECES ,bip.EX_WT AS GWT ,bip.AMOUNT_USD AS AMOUNT_CUR ,bip.CONSIGNEE_NAME ,CONCAT(bip.CONSIGNEE_ADDRESS_1, bip.CONSIGNEE_ADDRESS_2) AS CONSIGNEE_ADDRESS ,bip.AR_DATE ,bip.REGISTER_DATE_TIME AS PO_DATE FROM TB_BMS_IN_PLAN bip WITH (NOLOCK) WHERE bip.MBL_NO = #{srchMblNo}
AND bip.BL_NO = #{srchNo}

/* BmsCargoAbnormalMapper.selectAbnormalDeleteCheck : 하기이상결과보고 삭제 전 체크 */ SELECT ab.OD_JOB_NO ,ab.SEQ_NO_ID ,ab.ABNORMAL_CODE ,ab.MRN ,ab.HBL_NO ,ab.SEND_DATE ,(SELECT ISNULL(CONVERT(VARCHAR(10), SEND_DATE, 23), 'N') FROM TB_ECM_OD_PANTOS_ABNORMAL WHERE OD_JOB_NO = ab.OD_JOB_NO AND SEQ_NO_ID = 2) AS MGN_MFN FROM TB_ECM_OD_PANTOS_ABNORMAL ab WHERE (
(ab.MRN = #{item.mrn})
)

mapper.delete:
/* BmsCargoAbnormalMapper.deleteAbnormalList : 하기이상결과보고 delete */ DELETE FROM TB_ECM_OD_PANTOS_ABNORMAL WHERE (
(MRN = #{item.mrn})
(OD_JOB_NO = #{item.odJobNo} AND ABNORMAL_CODE = #{item.abnormalCode})
)

/* BmsCargoAbnormalMapper.deleteAbnormalList : 하기이상결과보고  delete */
	DELETE FROM TB_ECM_OD_SPECIAL_ITEM
	WHERE OD_JOB_NO IN(#{item.OD_JOB_NO})

mapper.update:
/* BmsCargoAbnormalMapper.updateAbnormal : 하기이상결과보고 update */
	UPDATE 
		TB_ECM_OD_PANTOS_ABNORMAL 
	SET
		PIECES = #{pieces}
		,GWT = #{gwt}
		,CNT = #{cnt}
		,ABNORMAL_CODE = #{editAbnormalCode}
		,EX_CT = #{hblPieces}	
		,EX_WT = #{hblGwt}
		,UPDATE_USER_ID = #{registerUserId}
		,UPDATE_DATE_TIME = GETDATE()	
	WHERE 
		OD_JOB_NO = #{odJobNo}
		AND ABNORMAL_CODE = #{abnormalCode}

/* BmsCargoAbnormalMapper.updateAbnormalAdditional : 하기이상결과보고신고 삭제건 ad update */
	UPDATE ad
	SET   ad.ABNORMAL_MFN_DATE = NULL
		, ad.ABNORMAL_MFN_YN = NULL
	
	 
		, ad.ABNORMAL_DATE = NULL
	
	
		, ad.ABNORMAL_DATE = #{sendDate}
	
	
	FROM TB_ECM_OD_ADDITIONAL ad
	INNER JOIN TB_ECM_OD_ABNORMAL abnormal ON abnormal.MRN = #{mrn}
 	WHERE abnormal.OD_JOB_NO = #{odJobNo} AND abnormal.SEQ_NO_ID = #{seqNoId}

