mapper.insert:
	/* BmsCargoAbnormalMapper.insertAbnormal : 하기이상결과보고  insert */
	INSERT INTO TB_ECM_OD_ABNORMAL(
		   OD_JOB_NO
		  ,SEQ_NO_ID
		  ,ABNORMAL_CODE
		  ,MRN
		  ,MSN
		  ,VESSEL_FLIGHT
		  ,DISC_WH_CODE
		  ,AR_DATE
		  ,PIECES
		  ,GWT
		  ,CNT
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)
	SELECT
		 od.OD_JOB_NO
		,#{seqNoId}
		,#{abnormalCode}
		,#{mrn}
		,#{msn}
		,#{vesselFlight}
		,#{discWhCode}
		,#{arDate}
		
		
		,0
		,0
		,od.PIECES
		
		
			
			
			,#{pieces}
			,#{gwt}
			
			
			,od.PIECES
			,od.GWT
			
			
		,od.PIECES
		
		
			,#{pieces}
			,#{gwt}
			,od.PIECES-#{pieces}
		
		
		,#{pieces}
		,#{gwt}
		,0
		
		
		,#{registerUserId}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())
		,#{registerUserId}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())		
	FROM TB_ECM_OD od
	
		
 		WHERE od.OD_JOB_NO IN (#{item})
 		
 		
 		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
 		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
 		WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
 		AND od.BL_TYPE_MH = 'H'
 		
 		
 		
		WHERE od.OD_JOB_NO = #{odJobNo}

	/* BmsCargoAbnormalMapper.insertBmsInPlanAbnormal : 하기이상결과보고  insert(반입예정데이터) */
	INSERT INTO TB_ECM_OD_ABNORMAL(
		   OD_JOB_NO
		  ,SEQ_NO_ID
		  ,ABNORMAL_CODE
		  ,MRN
		  ,MSN
		  ,VESSEL_FLIGHT
		  ,DISC_WH_CODE
		  ,AR_DATE
		  ,PIECES
		  ,GWT
		  ,CNT
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)
	SELECT
		 bip.IN_PLAN_NO
		,#{seqNoId}
		,#{abnormalCode}
		,#{mrn}
		,#{msn}
		,#{vesselFlight}
		,#{discWhCode}
		,#{arDate}
		
		
		,0
		,0
		,bip.EX_CT
		
		
			
			
			,#{pieces}
			,#{gwt}
			
			
			,bip.EX_CT
			,bip.EX_WT
			
			
		,bip.EX_CT
		
		
			,#{pieces}
			,#{gwt}
			,bip.EX_CT-#{pieces}
		
		
		,#{pieces}
		,#{gwt}
		,0
		
		
		,#{registerUserId}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())
		,#{registerUserId}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())		
	FROM TB_BMS_IN_PLAN bip WITH (NOLOCK)
	
		
 		WHERE bip.IN_PLAN_NO IN (#{item})
 		
 		
		WHERE bip.IN_PLAN_NO = #{odJobNo}

/* BmsCargoAbnormalMapper.insertAbnormalMgnMfn : 적하목록 마스터로 MGN or SHT후 MFN생성 */
INSERT INTO TB_ECM_OD_ABNORMAL(
	   OD_JOB_NO
	  ,SEQ_NO_ID
	  ,ABNORMAL_CODE
	  ,MRN
	  ,MSN
	  ,VESSEL_FLIGHT
	  ,DISC_WH_CODE
	  ,AR_DATE
	  ,PIECES
	  ,GWT
	  ,CNT
	  ,REGISTER_USER_ID
	  ,REGISTER_DATE_TIME
	  ,UPDATE_USER_ID
	  ,UPDATE_DATE_TIME
)VALUES(
	   #{odJobNo}
	  ,#{seqNoId}
	  ,#{abnormalCode}
	  ,#{mrn}
	  ,#{msn}
	  ,#{vesselFlight}
	  ,#{discWhCode}
	  ,#{arDate}
	  ,#{pieces}
	  ,#{gwt}
	  ,#{hblPieces}
	  ,#{registerUserId}
	  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	  ,#{registerUserId}
	  ,DATEADD(HOUR, ${gmtTime}, GETDATE())		
)

	/* BmsCargoAbnormalMapper.insertSpecialManageItem : 별도관리물품  insert */
	INSERT INTO TB_ECM_OD_SPECIAL_ITEM
	(
		OD_JOB_NO
		, SEQ_NO_ID
		, MANAGE_TYPE
		, AR_DATE
		, FLIGHT_NO
		, DEST_PORT
		, PIECES
		, ITEM_DESC
		, GWT
	)	

	
	SELECT od.OD_JOB_NO
		,(SELECT ISNULL(MAX(SEQ_NO_ID),0) + 1 FROM TB_ECM_OD_SPECIAL_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO)
		,#{MANAGE_TYPE}
		,#{AR_DATE}
		,#{FLIGHT_NO}
		,#{DEST_PORT}
		,#{PIECES}
		,#{ITEM_DESC}
		,#{GWT}
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
			 			ON od.OD_JOB_NO = ad.OD_JOB_NO
	WHERE od.MASTER_OD_JOB_NO = #{MASTER_OD_JOB_NO}
	AND od.BL_TYPE_MH = 'H'
	
	
	
	VALUES
	(
		#{OD_JOB_NO}
		,(SELECT ISNULL(MAX(SEQ_NO_ID),0) + 1 FROM TB_ECM_OD_SPECIAL_ITEM WHERE OD_JOB_NO = #{OD_JOB_NO} )
		,#{MANAGE_TYPE}
		,#{AR_DATE}
		,#{FLIGHT_NO}
		,#{DEST_PORT}
		,#{PIECES}
		,#{ITEM_DESC}
		,#{GWT}
	)

/* BmsCargoAbnormalMapper.insertSpecialManageItemMgnMfn : 별도관리물품  insert */
INSERT INTO TB_ECM_OD_SPECIAL_ITEM(
	   OD_JOB_NO
	  ,SEQ_NO_ID
	  ,MANAGE_TYPE
	  ,AR_DATE
	  ,FLIGHT_NO
	  ,DEST_PORT
	  ,PIECES
	  ,ITEM_DESC
	  ,GWT
)VALUES(
	   #{OD_JOB_NO}
	  ,(SELECT ISNULL(MAX(SEQ_NO_ID),0) + 1 FROM TB_ECM_OD_SPECIAL_ITEM WHERE OD_JOB_NO = #{OD_JOB_NO})
	  ,#{MANAGE_TYPE}
	  ,#{AR_DATE}
	  ,#{FLIGHT_NO}
	  ,#{DEST_PORT}
	  ,#{PIECES}
	  ,#{ITEM_DESC}
	  ,#{GWT}
)

/* BmsCargoAbnormalMapper.insertAbnormalOrderAdditional : MGN이 없는 MFN 발생시 orderAdditional insert */ INSERT INTO TB_ECM_OD_ADDITIONAL( OD_JOB_NO ,CUSTOMS_ID_VERIFY ,MASTER_OD_JOB_NO ,MBL_NO ,HBL_NO ,CD_TYPE ,BL_TYPE_MH ,HSN
) SELECT TOP 1 #{odJobNo} ,'NV' ,MASTER_OD_JOB_NO ,MBL_NO ,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) ,#{cdType} ,'H' ,#{hsn}
FROM TB_ECM_OD WHERE OD_JOB_NO = #{masterOdJobNo}

/* BmsCargoAbnormalMapper.insertAbnormalOrder : MGN이 없는 MFN 발생시 order insert */ INSERT INTO TB_ECM_OD( OD_JOB_NO ,ENT_CODE ,ENT_BUSINESS_CODE ,SOLUTION ,BOUND ,BOUND_TYPE ,PO_DATE ,CUST_CODE_LV1 ,BL_TYPE_MH ,BL_TYPE_IERT ,CONSOL_YN ,MASTER_OD_JOB_NO ,MBL_NO ,HBL_NO ,MRN ,MSN ,HSN ,CD_TYPE
,CD_USE_TYPE ,ECM_TYPE
,VESSEL_FLIGHT ,ORIG_CODE ,ORIG_NAME ,OB_DATE ,OB_TIME ,DEST_CODE ,DEST_NAME ,ORIG_COUNTRY ,AR_DATE ,AR_TIME ,PIECES ,GWT ,GWT_LBS ,AMOUNT_LOC ,AMOUNT_CUR ,AMOUNT_USD ,FINISH_YN ,INPUT_METHOD ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME ) SELECT TOP 1 #{odJobNo} ,ENT_CODE ,ENT_BUSINESS_CODE ,SOLUTION ,BOUND ,BOUND_TYPE ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,CUST_CODE_LV1 ,'H' ,BL_TYPE_IERT ,CONSOL_YN ,MASTER_OD_JOB_NO ,MBL_NO ,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) ,MRN ,MSN ,#{hsn} ,#{cdType}
,#{cdUseType} ,#{ecmType}
,VESSEL_FLIGHT ,ORIG_CODE ,ORIG_NAME ,OB_DATE ,OB_TIME ,DEST_CODE ,DEST_NAME ,ORIG_COUNTRY ,AR_DATE ,AR_TIME ,#{pieces} ,#{gwt} ,#{gwt} * 2.20462262 ,0 ,0 ,0 ,FINISH_YN ,'WEB' ,#{registerUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,#{registerUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) FROM TB_ECM_OD WHERE OD_JOB_NO = #{masterOdJobNo}

mapper.update:
/* BmsCargoAbnormalMapper.updateMblCorrectByAb : 적하정정 update */
	UPDATE TB_EDI_MOD_MBL SET
		   HBL_CNT = #{hblCnt}
		  ,MOD_REQ_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE MOD_JOB_NO = #{modJobNo}

/* BmsCargoAbnormalMapper.updateDiscWhCode : 적하정정 하기장소 업데이트 */
	UPDATE TB_ECM_OD SET DISC_WH_CODE = #{discWhCode}
	WHERE OD_JOB_NO = #{odJobNo}

/* BmsCargoAbnormalMapper.updateDiscItemCode : 적하정정 하기물품코드 업데이트 */
	UPDATE TB_ECM_OD_ADDITIONAL SET DISC_ITEM_CODE = #{discItemCode}
	WHERE OD_JOB_NO = #{odJobNo}

mapper.select:
		/* BmsCargoAbnormalMapper.getSeqNoIdByAb : 적하정정 House seq_id 추출 */
		SELECT
			 ISNULL(MAX(hbl.SEQ_NO_ID),0) + 1 AS SEQ_NO_ID
			
			,MAX(hblOd.SEQ_NO_ID) AS HBL_SEQ_NO_ID
			,(SELECT ISNULL(MAX(CNTR_SEQ_NO_ID),0) + 1 FROM TB_EDI_MOD_CONTAINER WHERE MOD_JOB_NO = #{modJobNo} AND SEQ_NO_ID = MAX(hblOd.SEQ_NO_ID)) AS CNTR_SEQ_NO_ID
			
		FROM TB_EDI_MOD_HBL hbl
			 
			 LEFT JOIN TB_EDI_MOD_HBL hblOd
			 		   ON hblOd.MOD_JOB_NO = hbl.MOD_JOB_NO
			 		   AND hblOd.OD_JOB_NO = #{odJobNo}
			 
		WHERE hbl.MOD_JOB_NO = #{modJobNo}

/* BmsCargoAbnormalMapper.getIsModData : 적하정정 존재여부 추출 */
SELECT COUNT(*)
FROM TB_EDI_MOD_HBL 
WHERE MOD_JOB_NO = #{modJobNo}
AND OD_JOB_NO IN (
				
					#{item.odJobNo}
				
				)

	
	
	AND SINGLE_MOD_CODE = #{singleModCode}
	
	
	AND SINGLE_MOD_CODE IN (#{item})

/* BmsCargoAbnormalMapper.getIsModContainerData : 적하정정 존재여부 추출 */
SELECT COUNT(*)
FROM TB_EDI_MOD_HBL hbl
	 INNER JOIN TB_EDI_MOD_CONTAINER cntr
	 			ON cntr.MOD_JOB_NO = hbl.MOD_JOB_NO
	 			AND cntr.SEQ_NO_ID = hbl.SEQ_NO_ID 
WHERE hbl.MOD_JOB_NO = #{modJobNo}
AND hbl.OD_JOB_NO IN (#{item.odJobNo})
AND cntr.CNTR_MOD_TYPE = #{cntrModType}


AND ((cntr.CNTR_NO = #{item.cntrNo} AND cntr.CNTR_MOD_CODE = #{item.cntrModCode}))


AND cntr.CNTR_NO IN (#{item.cntrNo})


AND cntr.CNTR_NO = #{cntrNo}

