/* BmsCargoAbnormalMapper.insertHblCorrectByAb : 적하정정 insert */
INSERT INTO TB_EDI_MOD_HBL(
	MOD_JOB_NO
	,SEQ_NO_ID
	,HSN
	,HBL_NO
	,OD_JOB_NO
	,MOD_TYPE
	,MOD_REASON
	,SINGLE_MOD_CODE
	,SINGLE_MOD_REASON_CODE
	,BEFORE_VALUE
	,AFTER_VALUE
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
)VALUES(
	#{modJobNo}
	,#{seqNoId}
	,#{hsn}
	,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),'')))
	,#{odJobNo}
	,#{modType}
	,#{modReason}
	,#{singleModCode}
	,#{singleModReasonCode}
	,#{beforeValue}
	,NULL
	,#{registerUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
)

