/* BmsCargoAbnormalMapper.updateOrderContainer : 적하정정시 컨테이너 update */
	UPDATE TB_ECM_OD_CONTAINER SET
		  
		  
		  
		  CNTR_CODE = #{item.cntrCode}
		  ,CNTR_EDI_CODE = #{item.afterValue}
		  
		  
		  CNTR_SEAL_NO_1 = #{item.afterValue}
		  
		  
		  CNTR_SEAL_NO_2 = #{item.afterValue}
		  
		  
		  CNTR_NO = #{item.afterValue}
		  
		  
		  CNTR_SEAL_NO_3 = #{item.afterValue}
		  
		  
		  PIECES = #{item.afterValue}
		  
		  
		  
	WHERE OD_JOB_NO = #{odJobNo}
	AND CNTR_NO = #{cntrNo};
	UPDATE TB_EDI_MOD_CONTAINER SET
		  
		  
		  
		  CNTR_CODE = #{item.cntrCode}
		  ,CNTR_EDI_CODE = #{item.afterValue}
		  
		  
		  CNTR_SEAL_NO_1 = #{item.afterValue}
		  
		  
		  CNTR_SEAL_NO_2 = #{item.afterValue}
		  
		  
		  CNTR_NO = #{item.afterValue}
		  
		  
		  CNTR_SEAL_NO_3 = #{item.afterValue}
		  
		  
		  PIECES = #{item.afterValue}
		  
		  
		  
	WHERE MOD_JOB_NO = #{modJobNo}
	AND SEQ_NO_ID = #{seqNoId}
