/* BmsCargoAbnormalMapper.insertExcelAbnormal : 하기이상결과보고 Excel insert */
INSERT INTO TB_ECM_OD_ABNORMAL
(
	OD_JOB_NO
	, SEQ_NO_ID
	, ABNORMAL_CODE
	, MRN
	, MSN
	, VESSEL_FLIGHT
	, DISC_WH_CODE
	, AR_DATE
	, PIECES
	, GWT
	, CNT
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
	, UPDATE_USER_ID
	, UPDATE_DATE_TIME)			
SELECT
	od.OD_JOB_NO
	,(SELECT ISNULL(MAX(SEQ_NO_ID),0) + 1 FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO )
	, #{ABNORMAL_CODE}
	, #{MRN}
	, #{MSN}
	, #{VESSEL_FLIGHT}
	, #{DISC_WH_CODE}
	, #{AR_DATE}
	, #{PIECES}
	, #{GWT}
	, #{CNT}
	,#{registerUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,#{registerUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())		
FROM TB_ECM_OD od			
WHERE MBL_NO = LTRIM(RTRIM(REPLACE(#{MBL_NO},char(9),'')))
AND HBL_NO = LTRIM(RTRIM(REPLACE(#{HBL_NO},char(9),'')));

/* BmsCargoAbnormalMapper.insertBmsInPlanExcelAbnormal : 하기이상결과보고 Excel insert(반입예정데이터) */
IF EXISTS(
	SELECT
		OD_JOB_NO
	FROM
		TB_ECM_OD_PANTOS_ABNORMAL
	WHERE
		MRN = #{mrn}
		AND MBL_NO = #{mblNo}
		AND HBL_NO = #{hblNo}
		AND ABNORMAL_CODE = #{abnormalCode}
)
BEGIN
	UPDATE 
		TB_ECM_OD_PANTOS_ABNORMAL
	SET
		MRN = #{mrn}
			
		, LAST_POD_STATUS = 'BMS01'			
		
		, VESSEL_FLIGHT = #{vesselFlight}
		, ORIG_COUNTRY = #{origCountry}
		, AR_DATE = #{arDate}
		, PIECES = #{pieces}
		, GWT = #{gwt}
		, CNT = #{cnt}
		, EX_CT = #{hblPieces}
		, EX_WT = #{hblGwt}
		, UPDATE_USER_ID = #{registerUserId}
		, UPDATE_DATE_TIME = GETDATE()
	WHERE 
		MRN = #{mrn}
		AND MBL_NO = #{mblNo}
		AND HBL_NO = #{hblNo}
		AND ABNORMAL_CODE = #{abnormalCode};
END 
ELSE
	BEGIN 
		INSERT INTO TB_ECM_OD_PANTOS_ABNORMAL(
			OD_JOB_NO
			, SEQ_NO_ID
			, ABNORMAL_CODE
			, LAST_POD_STATUS
			, MRN
			
				, MSN
			
			
				, HSN
			
			, MBL_NO
			, HBL_NO
			, VESSEL_FLIGHT
			, ORIG_COUNTRY
			, DISC_WH_CODE
			, AR_DATE
			, PIECES
			, GWT
			, CNT
			, EX_CT
			, EX_WT
			, DECLARATION_DATE	
			, REGISTER_USER_ID
			, REGISTER_DATE_TIME
			, UPDATE_USER_ID
			, UPDATE_DATE_TIME
			, REMARKS
		)VALUES(
			#{odJobNo}
			, #{seqId}
			
			, #{abnormalCode}
			, 'BMS01'
			, #{mrn}
			
				, #{msn}
			
			
				, #{hsn}
			
			, #{mblNo}
			, #{hblNo}
			, #{vesselFlight}
			, #{origCountry}
			, #{discWhCode}
			, #{arDate}
			, #{pieces}
			, #{gwt}
			, #{cnt}
			, #{hblPieces}
			, #{hblGwt}
			, GETDATE()	
			, #{registerUserId}
			, GETDATE()	
			, #{registerUserId}
			, GETDATE()	
			, #{remarks}
		);
END

