mapper.select:
/* BmsCargoAbnormalMapper.selectSendBmsInPlanAbnormalities : 하기결과이상보고 대상 조회(반입예정데이터) */ SELECT OD_JOB_NO , SEQ_NO_ID , MBL_NO , HBL_NO , MRN , MSN , REPLACE(AR_DATE, '-', '') AS AR_DATE , VESSEL_FLIGHT , '' AS DEST_CODE , bus.BMS_CUSTOMS_CODE AS CUSTOMS_CODE , bus.BMS_CUSTOMS_DPT_CODE AS CUSTOMS_DPT_CODE , ABNORMAL_CODE , MRN AS MRN_ABNORMAL , CONVERT(VARCHAR(8), AR_DATE, 112) AS AR_DATE_ABNORMAL , CONVERT(VARCHAR(8), GETDATE(), 112) AS ISSUE_DATE , 'QQ' AS LINE_CODE , opt.SET_VALUE AS EDI_VENDER FROM TB_ECM_OD_PANTOS_ABNORMAL LEFT JOIN TB_SMS_ENT_BUSINESS bus ON bus.ENT_CODE = #{entCode} AND bus.ENT_BUSINESS_CODE = #{entBusinessCode} LEFT JOIN TB_SMS_ENT_BUS_OPTION opt ON opt.ENT_CODE = #{entCode} AND opt.ENT_BUSINESS_CODE = #{entBusinessCode} AND opt.OPTION_CODE = 'A13' WHERE (
MRN = #{item.mrn}
) ORDER BY MRN, OD_JOB_NO, SEQ_NO_ID

/* BmsCargoAbnormalMapper.selectSendAbnormalitiesAbnormal : 하기결과이상보고 대상 조회 */ SELECT od.HBL_NO ,od.PIECES ,od.GWT ,od.HSN ,od.MRN ,od.LINE_CODE ,abnormal.VESSEL_FLIGHT ,od.MBL_NO ,od.MSN ,od.DEST_CODE ,od.OD_JOB_NO ,CONVERT(VARCHAR(8), od.AR_DATE, 112) AS AR_DATE ,abnormal.ABNORMAL_CODE ,abnormal.PIECES AS PIECES_ABNORMAL ,abnormal.GWT AS GWT_ABNORMAL ,abnormal.DISC_WH_CODE ,abnormal.MRN AS MRN_ABNORMAL ,abnormal.MSN AS MSN_ABNORMAL ,abnormal.SEQ_NO_ID ,CONVERT(VARCHAR(8), abnormal.AR_DATE, 112) AS AR_DATE_ABNORMAL ,CASE abnormal.ABNORMAL_CODE WHEN 'MFN' THEN 2 ELSE 1 END AS SORT_SEQ_NO ,(SELECT OD_JOB_NO FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO AND SEQ_NO_ID = 1 AND SEND_DATE IS NULL) AS UPDATE_OD_JOB_NO ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM160' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_02 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM160' ) A ) AS ECM160_POD_JOB_NO FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ABNORMAL abnormal ON abnormal.OD_JOB_NO = od.OD_JOB_NO AND abnormal.SEND_DATE IS NULL WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo} AND(
(abnormal.OD_JOB_NO = #{item.odJobNo} AND abnormal.SEQ_NO_ID = #{item.seqNoId})
) ORDER BY od.OD_JOB_NO, SORT_SEQ_NO

/* BmsCargoAbnormalMapper.selectSendBmsInPlanAbnormalitiesAbnormal : 하기결과이상보고 대상 조회(반입예정데이터) */ SELECT HBL_NO AS HBL_NO , EX_CT AS PIECES , EX_WT AS GWT , MRN AS MRN , MSN AS MSN , HSN AS HSN , 'QQ' AS LINE_CODE , VESSEL_FLIGHT AS VESSEL_FLIGHT , MBL_NO AS MBL_NO , OD_JOB_NO AS OD_JOB_NO , REPLACE(AR_DATE, '-', '') AS AR_DATE , ABNORMAL_CODE AS ABNORMAL_CODE , PIECES AS PIECES_ABNORMAL , GWT AS GWT_ABNORMAL , 'PEX' AS DISC_WH_CODE , MRN AS MRN_ABNORMAL , MSN AS MSN_ABNORMAL , SEQ_NO_ID AS SEQ_NO_ID , CONVERT(VARCHAR(8), AR_DATE, 112) AS AR_DATE_ABNORMAL , CASE ABNORMAL_CODE WHEN 'MFN' THEN 2 ELSE 1 END AS SORT_SEQ_NO
FROM TB_ECM_OD_PANTOS_ABNORMAL WHERE MRN = #{masterMrn}
ORDER BY OD_JOB_NO

mapper.update:
/* BmsCargoAbnormalMapper.updateSendAbnormalitiesReportd : 하기결과이상보고 신고 업데이트 */ UPDATE ad SET ad.ABNORMAL_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,ad.ABNORMAL_MFN_DATE = CASE WHEN abnormal.ABNORMAL_CODE IN('MGN', 'SHT') THEN DATEADD(DAY, 15, abnormal.AR_DATE) ELSE NULL END
,ad.LAST_POD_STATUS = CASE WHEN ISNULL(ad.LAST_POD_STATUS, '') < 'ECM160' THEN 'ECM160' ELSE ad.LAST_POD_STATUS END
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ABNORMAL abnormal ON abnormal.OD_JOB_NO = od.OD_JOB_NO AND abnormal.SEND_DATE IS NULL AND(
(abnormal.OD_JOB_NO = #{item.odJobNo} AND abnormal.SEQ_NO_ID = #{item.seqNoId})
) INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.MASTER_OD_JOB_NO IN(#{item.OD_JOB_NO});
UPDATE abnormal SET abnormal.SEND_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ABNORMAL abnormal ON abnormal.OD_JOB_NO = od.OD_JOB_NO AND abnormal.SEND_DATE IS NULL AND(
(abnormal.OD_JOB_NO = #{item.odJobNo} AND abnormal.SEQ_NO_ID = #{item.seqNoId})
) WHERE od.MASTER_OD_JOB_NO IN(#{item.OD_JOB_NO});

/* BmsCargoAbnormalMapper.updateSendBmsInPlanAbnormalitiesReportd : 하기결과이상보고 신고 업데이트(반입예정데이터) */ UPDATE TB_ECM_OD_ABNORMAL SET LAST_POD_STATUS = 'BMS03' , SEND_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) WHERE SEND_DATE IS NULL AND(
(OD_JOB_NO = #{item.odJobNo} AND SEQ_NO_ID = #{item.seqNoId})
)

mapper.select:
/* BmsCargoAbnormalMapper.selectEditPopupSearchList : 하기결과이상보고 - 수정 팝업 조회 */ SELECT OD_JOB_NO , MRN , MSN , HSN , VESSEL_FLIGHT , ORIG_COUNTRY , AR_DATE , MBL_NO , HBL_NO , EX_CT AS HBL_PIECES , EX_WT AS HBL_GWT , PIECES , GWT , CNT , ABNORMAL_CODE , LAST_POD_STATUS FROM TB_ECM_OD_PANTOS_ABNORMAL WHERE
MRN = #{mrn}
HBL_NO = #{hblNo}

/* BmsCargoAbnormalMapper.selectAbnormalResultList : 하기이상보고 결과 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT * FROM ( SELECT A.OD_JOB_NO , A.HBL_NO
, CONVERT( CHAR(19), COALESCE( FIRST_MGN.FIRST_MGN_DECLARATION_DATE, A.DECLARATION_DATE ), 20 ) AS DECLARATION_DATE , DATEDIFF( DAY, COALESCE( FIRST_MGN.FIRST_MGN_DECLARATION_DATE, A.DECLARATION_DATE ), GETDATE() ) + 1 AS ELAPSE_DATE , G.MBL_NO AS SEND_MGN_MBL , NF.MBL_NO AS NO_CARGO_MFN_MBL , CASE WHEN ISNULL(G.OD_JOB_NO, '') <> '' THEN 'Y' ELSE 'N' END AS MGN_YN , CASE WHEN ISNULL(F.OD_JOB_NO, '') <> '' THEN 'Y' ELSE 'N' END AS MFN_YN , A.MANIFEST_DEL_YN , A.ABNORMAL_CODE , CASE WHEN ISNULL(NF.MBL_NO, '') <> '' THEN CONCAT(NF.PIECES, '/', CONVERT(NUMERIC (5,1), NF.GWT)) ELSE '' END AS MANIFEST_ADD , '' AS RESULT_DETAIL , A.REMARKS , ISNULL(P.IN_YN, 'N') AS IN_YN , CASE WHEN ISNULL(G.LAST_POD_STATUS, '') = 'BMS04' THEN 'Y' ELSE 'N' END AS MGN_RAQ_YN , CASE WHEN ISNULL(F.LAST_POD_STATUS, '') = 'BMS04' THEN 'Y' WHEN ISNULL(NF.LAST_POD_STATUS, '') = 'BMS04' THEN 'Y' ELSE 'N' END AS MFN_RAQ_YN , ROW_NUMBER() OVER (PARTITION BY A.HBL_NO ORDER BY A.OD_JOB_NO) AS RN , P.ORIG_COUNTRY , CAST(I.CARRYIN_DATE + ' ' + I.CARRYIN_TIME AS DATETIME) AS CARRYIN_DATE , CASE WHEN ISNULL(MRN_STATUS.HAS_MGN, 0) = 1 AND ISNULL(MRN_STATUS.HAS_NON_MGN, 0) = 0 THEN 'Y' ELSE 'N' END AS MRN_ONLY_MGN_YN , MRN_STATUS.MGN_LAST_POD_STATUS AS MRN_MGN_LAST_POD_STATUS , CASE WHEN MRN_STATUS2.ABNORMAL_CODE_SUM = 0 THEN 'N' ELSE 'Y' END AS NOT_MGN_CODE_YN , CASE WHEN MRN_STATUS2.RAQ_SUM = 0 THEN 'N' WHEN MRN_STATUS2.ABNORMAL_CODE_SUM = MRN_STATUS2.RAQ_SUM THEN 'Y' ELSE 'N' END AS NOT_MGN_CODE_ALL_RAQ_YN , A.LAST_POD_STATUS AS LAST_POD_STATUS , ISNULL(I.IN_NO, 0) AS IN_NO FROM TB_ECM_OD_PANTOS_ABNORMAL A WITH (NOLOCK) LEFT JOIN ( SELECT GA.OD_JOB_NO, GA.MRN, GA.MBL_NO, GA.HBL_NO, GA.SEND_DATE, GA.DECLARATION_DATE, GA.ABNORMAL_CODE, GA.LAST_POD_STATUS FROM TB_ECM_OD_PANTOS_ABNORMAL GA WITH (NOLOCK) WHERE GA.ABNORMAL_CODE = 'MGN'
) G ON G.MBL_NO = A.MBL_NO AND G.HBL_NO = A.HBL_NO LEFT JOIN ( SELECT GA.OD_JOB_NO, GA.MRN, GA.MBL_NO, GA.HBL_NO, GA.SEND_DATE, GA.DECLARATION_DATE, GA.ABNORMAL_CODE, GA.LAST_POD_STATUS FROM TB_ECM_OD_PANTOS_ABNORMAL GA WITH (NOLOCK) WHERE GA.ABNORMAL_CODE = 'MFN'
) F ON F.MBL_NO = A.MBL_NO AND F.HBL_NO = A.HBL_NO LEFT JOIN ( SELECT FA.OD_JOB_NO, FA.MRN, FA.MBL_NO, FA.HBL_NO, FA.PIECES, FA.GWT, FA.SEND_DATE, FA.DECLARATION_DATE, FA.ABNORMAL_CODE, FA.LAST_POD_STATUS FROM TB_ECM_OD_PANTOS_ABNORMAL FA WITH (NOLOCK) WHERE FA.ABNORMAL_CODE = 'MFN' AND NOT EXISTS( SELECT 1 FROM TB_BMS_IN_PLAN P WITH (NOLOCK) WHERE P.OD_JOB_NO = FA.OD_JOB_NO )
) NF ON NF.MBL_NO = A.MBL_NO AND NF.HBL_NO = A.HBL_NO
LEFT JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON A.MBL_NO = P.MBL_NO AND A.HBL_NO = P.BL_NO LEFT JOIN TB_BMS_IN I WITH (NOLOCK) ON I.IN_PLAN_NO = P.IN_PLAN_NO OUTER APPLY ( SELECT MAX(CASE WHEN GA.ABNORMAL_CODE = 'MGN' THEN 1 ELSE 0 END) AS HAS_MGN, MAX(CASE WHEN GA.ABNORMAL_CODE <> 'MGN' THEN 1 ELSE 0 END) AS HAS_NON_MGN, MAX(CASE WHEN GA.ABNORMAL_CODE = 'MGN' THEN GA.LAST_POD_STATUS ELSE NULL END) AS MGN_LAST_POD_STATUS FROM TB_ECM_OD_PANTOS_ABNORMAL GA WITH (NOLOCK) WHERE GA.MRN = A.MRN ) MRN_STATUS OUTER APPLY ( SELECT SUM(CASE WHEN GA.ABNORMAL_CODE <> 'MGN' THEN 1 ELSE 0 END) AS ABNORMAL_CODE_SUM, SUM(CASE WHEN GA.ABNORMAL_CODE <> 'MGN' AND GA.LAST_POD_STATUS = 'BMS04' THEN 1 ELSE 0 END) AS RAQ_SUM FROM TB_ECM_OD_PANTOS_ABNORMAL GA WITH (NOLOCK) WHERE GA.MRN = A.MRN ) MRN_STATUS2 OUTER APPLY ( SELECT MIN(MGN.DECLARATION_DATE) AS FIRST_MGN_DECLARATION_DATE FROM TB_ECM_OD_PANTOS_ABNORMAL MGN WITH (NOLOCK) WHERE MGN.MBL_NO = A.MBL_NO AND MGN.HBL_NO = A.HBL_NO AND MGN.ABNORMAL_CODE = 'MGN' ) FIRST_MGN WHERE 1 = 1
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchDateGbn} >= CONVERT(CHAR(10), #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(CHAR(10), #{srchEndDate}, ${srchDateFormat}))
AND A.MANIFEST_DEL_YN IN ('Y', 'N')
AND A.MANIFEST_DEL_YN = 'Y'
AND A.MANIFEST_DEL_YN = 'N'
AND A.OD_JOB_NO IN (
#{item.odJobNo}
)
) t WHERE t.RN = 1
AND ( ( t.MRN_ONLY_MGN_YN = 'N' AND t.LAST_POD_STATUS = 'BMS04' AND t.MFN_RAQ_YN = 'Y' AND t.IN_NO > 0 AND t.MFN_YN = 'Y' ) OR ( t.MRN_ONLY_MGN_YN = 'Y' AND t.MFN_RAQ_YN = 'Y' AND ISNULL(t.MRN_MGN_LAST_POD_STATUS, '') = 'BMS04' ) OR ( t.MGN_YN = 'N' AND t.LAST_POD_STATUS = 'BMS04' AND t.IN_NO > 0 AND t.NOT_MGN_CODE_ALL_RAQ_YN = 'Y' ) )
AND NOT ( ( t.MRN_ONLY_MGN_YN = 'N' AND t.LAST_POD_STATUS = 'BMS04' AND t.MFN_RAQ_YN = 'Y' AND t.IN_NO > 0 AND t.MFN_YN = 'Y' ) OR ( t.MRN_ONLY_MGN_YN = 'Y' AND t.MFN_RAQ_YN = 'Y' AND ISNULL(t.MRN_MGN_LAST_POD_STATUS, '') = 'BMS04' ) OR ( t.MGN_YN = 'N' AND t.LAST_POD_STATUS = 'BMS04' AND t.IN_NO > 0 AND t.NOT_MGN_CODE_ALL_RAQ_YN = 'Y' ) )

/* BmsCargoAbnormalMapper.selectHblInPlanInfoList : 다중 HBL 추가 반입예정정보 조회 */ WITH HBL_NOS AS ( SELECT HBL_NO FROM ( VALUES
(CAST(#{item} AS VARCHAR(50)))
) AS H(HBL_NO) ), LATEST_INPLAN AS ( SELECT A.* FROM( SELECT BL_NO ,EX_CT ,EX_WT ,ROW_NUMBER() OVER (PARTITION BY BL_NO ORDER BY IN_PLAN_NO DESC) AS RN FROM TB_BMS_IN_PLAN WITH (NOLOCK) WHERE BL_NO IN
#{item}
) A WHERE A.RN = 1 ) SELECT H.HBL_NO ,ISNULL(P.EX_CT, 0) AS EX_CT ,ISNULL(P.EX_WT, 0) AS EX_WT FROM HBL_NOS H LEFT JOIN LATEST_INPLAN P ON P.BL_NO = H.HBL_NO
